import React, { useEffect, useState } from 'react';
import { patientApi } from '../../api/patientApi';
import Card from '../../components/Card';
import Loader from '../../components/Loader';
import ErrorBox from '../../components/ErrorBox';

const MyAppointments = () => {
  const [appointments, setAppointments] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    const fetchAppointments = async () => {
      try {
        const response = await patientApi.getAppointments();
        if (response.success) {
          const sorted = response.appointments.sort((a, b) => {
            return new Date(b.appointmentDate) - new Date(a.appointmentDate);
          });
          setAppointments(sorted);
        }
      } catch (err) {
        setError(err.response?.data?.message || 'Failed to fetch appointments');
      } finally {
        setLoading(false);
      }
    };

    fetchAppointments();
  }, []);

  if (loading) return <Loader />;

  const getStatusBadge = (status) => {
    const badges = {
      CONFIRMED: 'badge-info',
      PENDING: 'badge-warning',
      COMPLETED: 'badge-success',
      CANCELLED: 'badge-danger'
    };
    return badges[status] || 'badge-gray';
  };

  return (
    <div className="p-6 max-w-7xl mx-auto">
      <div className="mb-8 fade-in">
        <h1 className="text-4xl font-bold text-gray-800 mb-2">My Appointments</h1>
        <p className="text-gray-600 text-lg">View and track all your appointments</p>
      </div>

      {error && <ErrorBox message={error} onClose={() => setError('')} />}

      {appointments.length > 0 ? (
        <div className="space-y-4">
          {appointments.map((appointment) => (
            <Card 
              key={appointment._id}
              hover
              className={`
                border-l-4 transition-all duration-200
                ${appointment.status === 'CONFIRMED' || appointment.status === 'PENDING' 
                  ? 'border-l-blue-500 hover:border-l-blue-600' 
                  : appointment.status === 'COMPLETED' 
                  ? 'border-l-green-500 hover:border-l-green-600' 
                  : 'border-l-red-500 hover:border-l-red-600'
                }
              `}
            >
              <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-4">
                <div className="flex-1">
                  <div className="flex items-center gap-4 mb-4">
                    <div className="w-16 h-16 bg-gradient-to-br from-blue-500 to-indigo-600 rounded-full flex items-center justify-center">
                      <span className="text-white font-bold text-xl">
                        Dr. {appointment.doctor?.user?.name?.charAt(0) || 'D'}
                      </span>
                    </div>
                    <div className="flex-1">
                      <h3 className="text-xl font-bold text-gray-800 mb-1">
                        Dr. {appointment.doctor?.user?.name || 'N/A'}
                      </h3>
                      <p className="text-blue-600 font-semibold">{appointment.doctor?.specialization || 'N/A'}</p>
                    </div>
                    <span className={`badge ${getStatusBadge(appointment.status)}`}>
                      {appointment.status}
                    </span>
                  </div>

                  <div className="grid grid-cols-1 md:grid-cols-3 gap-4 text-sm">
                    <div className="flex items-center gap-2 text-gray-700">
                      <svg className="w-5 h-5 text-blue-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" />
                      </svg>
                      <div>
                        <p className="text-gray-500 text-xs">Date</p>
                        <p className="font-semibold">{new Date(appointment.appointmentDate).toLocaleDateString('en-US', { 
                          weekday: 'short', 
                          year: 'numeric', 
                          month: 'short', 
                          day: 'numeric' 
                        })}</p>
                      </div>
                    </div>
                    <div className="flex items-center gap-2 text-gray-700">
                      <svg className="w-5 h-5 text-blue-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
                      </svg>
                      <div>
                        <p className="text-gray-500 text-xs">Time</p>
                        <p className="font-semibold">{appointment.slotTime?.startTime} - {appointment.slotTime?.endTime}</p>
                      </div>
                    </div>
                    <div className="flex items-center gap-2 text-gray-700">
                      <svg className="w-5 h-5 text-blue-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
                      </svg>
                      <div>
                        <p className="text-gray-500 text-xs">Reason</p>
                        <p className="font-semibold">{appointment.reason}</p>
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            </Card>
          ))}
        </div>
      ) : (
        <Card>
          <div className="text-center py-12">
            <svg className="w-16 h-16 text-gray-400 mx-auto mb-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" />
            </svg>
            <p className="text-gray-600 text-lg mb-4">No appointments found</p>
            <a href="/patient/doctors" className="text-blue-600 hover:text-blue-700 font-semibold">
              Book your first appointment →
            </a>
          </div>
        </Card>
      )}
    </div>
  );
};

export default MyAppointments;
